-- Queer Atlas: Pamplona, Oxford, Bergen, Santiago de Compostela and Salzburg.
-- Researched 2026-08-28. Only production-approved place and service types are used.
-- Idempotent: update by normalized city/name, otherwise insert.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_qari$
declare k text;
begin
  foreach k in array array['country:spain','country:united-kingdom','country:norway','country:austria'] loop
    if not exists(select 1 from public.qa_qari_profiles where destination_key=k and scope_type='country' and is_published=true) then
      raise exception 'Published QARI profile % is required before this city batch can run.', k;
    end if;
  end loop;
end;
$qa_require_qari$;

with src as (
 select * from jsonb_to_recordset($qa_cities$
[
 {"slug":"pamplona","name":"Pamplona","title":"Queer Pamplona","country":"Spain","country_code":"ES","latitude":42.8125,"longitude":-1.6458,"timezone":"Europe/Madrid","vibe":"civic, bilingual and quietly defiant","local_mood":"Pamplona's queer life is community-led: Harrotu provides a permanent public home, local collectives create lesbian, trans and all-community programming, and June Pride occupies the streets rather than a commercial gay strip.","queer_status":"Spain provides strong legal protection, while Pamplona adds a municipal LGTBI plan, confidential reporting and a specialist public centre; nightlife visibility remains modest outside Pride.","crowd_profile":"LGBTQI+ Navarrese people, lesbians, bi women, trans and non-binary residents, migrants, students, families, activists and allies meet through public programmes and collectives.","introduction":"Pamplona is best read through institutions rather than inherited bar lists. Harrotu is the durable anchor, with a library, meeting room, psychological support and changing cultural programme. Casa de las Mujeres hosts queer reading and lesbian-bi community formats. Iruña Harro brings these networks into public squares every June; no unsupported permanent gay-bar claim is added.","guide_items":[{"title":"About","text":"A strong public and associative ecosystem compensates for the lack of a dedicated commercial nightlife district."},{"title":"Districts","text":"Harrotu sits in the old centre on San Gregorio; Pride activity spreads through Recoletas, Baluarte, Plaza del Castillo and civic venues."},{"title":"Safety","text":"Use Harrotu's confidential LGTBIfobia observatory for incidents and maintain ordinary crowd awareness during San Fermín and Pride."},{"title":"Nightlife","text":"Follow Harrotu, Dekumas and Pride organisers; a host venue is only queer-centred when the named programme says so."},{"title":"Cost","text":"Community programming is often free, while San Fermín creates exceptional accommodation pressure and crowding."}],"guide_sources":[{"label":"Harrotu","url":"https://www.pamplona.es/temas/igualdad-y-lgtbi/harrotu"},{"label":"Pamplona Pride 2026","url":"https://www.pamplona.es/actualidad/noticias/el-ayuntamiento-de-pamplona-colabora-con-colectivos-y-asociaciones-lgtbi-en-el"},{"label":"Dekumas LBT","url":"https://dekumaslbt.mozellosite.com/actividades/"}],"safety_context":"Pamplona has strong public queer infrastructure but a small visible nightlife scene. Use current organiser information, report incidents through Harrotu and plan carefully around festival crowds.","qari_key":"country:spain"},
 {"slug":"oxford","name":"Oxford","title":"Queer Oxford","country":"United Kingdom","country_code":"GB","latitude":51.7520,"longitude":-1.2577,"timezone":"Europe/London","vibe":"historic, bookish and joyfully collegiate","local_mood":"Oxford combines two durable dedicated LGBTQ+ nightlife anchors with student societies, leather and gaming groups, queer arts, swimming and a citywide Pride network.","queer_status":"The city has visible civic support and a Pride dating to 2003, while the UK's wider legal and social climate still contains material trans-policy tension and uneven lived experience.","crowd_profile":"LGBTQIA+ residents, university and Brookes students, academics, trans groups, queer women, leather communities, gaymers, artists and visitors share small but active spaces.","introduction":"The Jolly Farmers is Oxford's crooked-walled queer living room; Plush is the dedicated late dance floor. Common Ground offers daytime community culture, and The Nest hosts ambitious queer-femme punk and arts programmes without being mislabelled gay every night. The scene rewards calendars, conversation and crossover between town and gown.","guide_items":[{"title":"About","text":"Oxford's small venue core carries an unusually broad network of recurring identity, hobby and welfare groups."},{"title":"Districts","text":"Paradise Street and Frewin Court hold the dedicated venues; Cowley Road and east Oxford carry more mixed cultural programming."},{"title":"Safety","text":"Use venue safer-space policies, plan late transport and remember that institutional prestige does not erase harassment or trans exclusion."},{"title":"Nightlife","text":"Start at Jolly Farmers, move to Plush for late dancing, and use official calendars for arts or group-specific events."},{"title":"Cost","text":"Drinks and central rooms are expensive; university terms, graduations and festivals push accommodation sharply upward."}],"guide_sources":[{"label":"Oxford Pride 2026 guide","url":"https://oxfordpride.uk/wp-content/uploads/2026/06/Oxford-Pride-Digital-Guide-2026.pdf"},{"label":"Oxford Pride","url":"https://oxfordpride.uk/"},{"label":"Oxford City LGBTQIA+ resources","url":"https://www.oxford.gov.uk/equality-diversity-inclusion/lgbtqia"}],"safety_context":"Oxford is visibly inclusive but not risk-free. Check event audience and accessibility, plan late travel beyond the compact centre and use local LGBTQ+ support rather than assuming universities cover every visitor.","qari_key":"country:united-kingdom"},
 {"slug":"bergen","name":"Bergen","title":"Queer Bergen","country":"Norway","country_code":"NO","latitude":60.3913,"longitude":5.3221,"timezone":"Europe/Oslo","vibe":"rain-polished, intimate and proudly open","local_mood":"Bergen has one dedicated full-time queer bar, Fincken, surrounded by a broadly inclusive city whose Pride festival activates cultural venues rather than creating a permanent gay district.","queer_status":"Norway has strong legal protection and Bergen's official tourism body openly supports LGBTIQ+ visitors; the small permanent venue count makes community organisations and event calendars essential.","crowd_profile":"Queer Bergen residents, students, sailors, artists, gay men, queer women, trans and non-binary people, migrants, families and west-coast visitors meet across bar and festival formats.","introduction":"Fincken is the non-negotiable anchor: café by day on Saturdays, pub and dance floor by night. Kvarteret and USF Verftet matter when Bergen Pride, student organisers or queer producers take over, but remain mixed cultural venues otherwise. Rain, compact streets and a strong voluntary sector shape the rhythm more than a conventional gayborhood.","guide_items":[{"title":"About","text":"Official visitor information confirms one dedicated queer bar; breadth arrives through Pride and community programming."},{"title":"Districts","text":"Fincken and Kvarteret sit close to the central university quarter; USF Verftet lies west at Nordnes."},{"title":"Safety","text":"Bergen is broadly welcoming, but use normal late-night awareness, respect identity-specific events and dress for heavy rain."},{"title":"Nightlife","text":"Support Fincken year-round and follow Bergen Pride or FRI Vestland for larger cultural nights."},{"title":"Cost","text":"Norwegian drinks and hotels are expensive; walking reduces transport costs and advance tickets help control the budget."}],"guide_sources":[{"label":"Visit Bergen LGBTIQ+ guide","url":"https://en.visitbergen.com/visitor-information/lgbtiq-travel-in-bergen-gay-bars-and-inclusive-experiences"},{"label":"Fincken","url":"https://www.fincken.no/"},{"label":"Bergen Pride","url":"https://www.bergenpride.no/"}],"safety_context":"Bergen combines high institutional inclusion with a very small permanent queer venue network. Use current programming, plan for weather and do not label every generally inclusive bar as a queer venue.","qari_key":"country:norway"},
 {"slug":"santiago_de_compostela","name":"Santiago de Compostela","title":"Queer Santiago de Compostela","country":"Spain","country_code":"ES","latitude":42.8782,"longitude":-8.5448,"timezone":"Europe/Madrid","vibe":"stone-built, student-minded and Galician-proud","local_mood":"Compostela's queer scene folds a drag-led club and feminist-friendly old-town bars into activist, university and municipal culture rather than a separate gay quarter.","queer_status":"Spain's strong legal baseline is reinforced by unanimous municipal commitments and anti-LGTBIfobia nightlife protocols, though recent local incidents show that formal support does not eliminate hate.","crowd_profile":"Galician LGBTQ+ residents, students, pilgrims, drag audiences, queer women, trans people, left-cultural crowds, artists and allies share the old town's compact late-night rooms.","introduction":"Bloom is the clear dedicated LGBT club and drag address. A Medusa provides feminist and lesbian-community history with cocktails and live music; Tarasca remains an inexpensive mixed late bar with queer goodwill. Avante LGBT+ and the city keep public memory, Pride and anti-hate work visible. A similarly named old-town pub is excluded because current operating evidence conflicts.","guide_items":[{"title":"About","text":"The scene is small but culturally embedded in a university and pilgrimage city with strong Galician identity."},{"title":"Districts","text":"Most nightlife sits inside the old town around Algalia, Entremuros and Mercado de Abastos; civic events use Mazarelos and other central squares."},{"title":"Safety","text":"The centre is walkable and generally calm, but harassment is possible; choose Troula Segura venues and avoid isolated late routes."},{"title":"Nightlife","text":"Use Bloom for dedicated LGBT programming, then match A Medusa or Tarasca to the desired music and crowd."},{"title":"Cost","text":"Drinks can be moderate, but pilgrimage peaks, university dates and festivals tighten central accommodation."}],"guide_sources":[{"label":"Compostela Pride 2026","url":"https://cimcompostela.santiagodecompostela.gal/es/la-alcaldesa-de-santiago-presenta-la-campana-contra-el-odio-red-cultura-y-orgullo-para-avanzar-contra-la-lgtbifobia/"},{"label":"Avante LGBT+","url":"https://avantelgbt.com/index.php/quen-somos/"},{"label":"Troula Segura","url":"https://cimcompostela.santiagodecompostela.gal/es/troula-segura-es/"}],"safety_context":"Santiago is compact and institutionally engaged, but recorded LGTBIfobia remains relevant. Prefer trained nightlife venues, travel with others late and use current local activist guidance.","qari_key":"country:spain"},
 {"slug":"salzburg","name":"Salzburg","title":"Queer Salzburg","country":"Austria","country_code":"AT","latitude":47.8095,"longitude":13.0550,"timezone":"Europe/Vienna","vibe":"baroque, theatrical and unexpectedly bold","local_mood":"Salzburg supports a permanent community bar, a men-only cruise venue and a deep calendar of drag, karaoke, film, food and culture that peaks during its ten-day Pride Festival.","queer_status":"Austria offers substantial protection, while HOSI Salzburg has built visible counselling and community infrastructure; the tourist centre's polish coexists with a scene dependent on named programmes.","crowd_profile":"LGBTQ+ Salzburg residents, gay men, queer women, trans people, fetish communities, artists, music workers, students, alpine visitors and allies meet across sharply different formats.","introduction":"HOSI Bar is the community heart; Dark Eagle serves an explicit men-only adult audience; Narrencastl mixes neighbourhood warmth with queer karaoke and travesty; Furo adds plant-based Pride brunch; ARGEkultur scales the scene into western Austria's largest queer club night. Salzburg's theatrical instincts make the calendar unusually rich for its size.","guide_items":[{"title":"About","text":"The permanent core is small, but HOSI's partnerships turn museums, restaurants, theatres and rooftops queer on named dates."},{"title":"Districts","text":"Andräviertel holds HOSI and Dark Eagle; Lehen has Narrencastl; Nonntal contains ARGEkultur."},{"title":"Safety","text":"Read men-only and adult-house rules, use normal tourist-centre awareness and plan late transport outside the old town."},{"title":"Nightlife","text":"Begin at HOSI Bar, choose Dark Eagle only if its scope fits, and book HOSI Fest or other programmed takeovers early."},{"title":"Cost","text":"Festival season and Christmas markets make rooms expensive; Pride events range from free community formats to ticketed club nights."}],"guide_sources":[{"label":"Queer Salzburg 2026","url":"https://www.queersalzburg.at/"},{"label":"HOSI Salzburg","url":"https://hosi.or.at/"},{"label":"Pride Week Salzburg","url":"https://www.salzburg.info/en/events/events-calendar/pride-week-salzburg_event_40064483"}],"safety_context":"Salzburg's dedicated organisations are visible and experienced, but venue identities vary widely. Confirm audience, tickets and access for every event and distinguish dedicated queer spaces from Pride-only hosts.","qari_key":"country:austria"}
]
$qa_cities$) c(slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_key text)
)
insert into public.qa_cities(slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,c.guide_items,c.guide_sources,date '2026-08-28',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now()) from src c cross join lateral(select destination_key,qari_score,summary,confidence from public.qa_qari_profiles where destination_key=c.qari_key and scope_type='country' and is_published=true order by reviewed_at desc nulls last limit 1) q
on conflict(slug) do update set name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

with raw_places as (
 select * from jsonb_to_recordset($qa_places$
[
 {"name":"Harrotu LGTBI Centre","city":"pamplona","type":"gallery","description":"Pamplona's permanent municipal queer home combines a specialist library, public meeting room, workshops, exhibitions and confidential support behind one visible old-town door.","hours":"Winter: Monday 17:00-20:30, Tuesday-Friday 10:30-13:30 and 17:00-20:30, Saturday 11:00-14:00; summer differs.","link":"https://www.pamplona.es/temas/igualdad-y-lgtbi/harrotu","location":"Calle San Gregorio 28, ground floor, 31001 Pamplona, Spain","lat":42.81711,"lng":-1.64689,"vibe":"public queer library and meeting room built for participation","q":"Free workshops may require registration; support appointments need direct contact.","best":"Visit during staffed hours for the mediatheque or attend a named community programme.","crowd":"LGBTQI+ residents, families, migrants, students, researchers and allies.","dress":"Everyday community casual.","staff":"Municipal LGTBI service managed with specialist community expertise and confidential protocols.","sources":["https://www.pamplona.es/temas/igualdad-y-lgtbi/harrotu"]},
 {"name":"Casa de las Mujeres de Pamplona","city":"pamplona","type":"gallery","description":"A feminist civic house where Dekumas runs queer reading, lesbian-bi gatherings and cultural work, giving women and non-binary people a programme-led alternative to nightlife.","hours":"Programme-led; queer listing applies only to named activities.","link":"https://www.pamplona.es/temas/igualdad-y-lgtbi","location":"Calle Aoiz 9, 31004 Pamplona, Spain","lat":42.81144,"lng":-1.63483,"vibe":"feminist public space activated by lesbian and queer organising","q":"Registration and audience rules vary by workshop or reading group.","best":"Attend a current Dekumas or Harrotu-listed session rather than arriving unannounced.","crowd":"Lesbian and bisexual women, trans and non-binary people, feminists and invited allies.","dress":"Comfortable community casual.","staff":"Queer identity belongs to documented hosted programmes; the civic venue itself serves a broader feminist public.","sources":["https://dekumaslbt.mozellosite.com/actividades/","https://www.pamplona.es/temas/igualdad-y-lgtbi/harrotu"]},

 {"name":"The Jolly Farmers","city":"oxford","type":"bar","description":"A gloriously crooked sixteenth-century pub that functions as Oxford's queer living room, hosting trans socials, leather gatherings, board gaymers, queer women and performers among low beams and pub warmth.","hours":"Open year-round; verify daily hours and event calendar.","link":"https://www.jollyfarmers.co.uk/","location":"20 Paradise Street, Oxford OX1 1LD, United Kingdom","lat":51.75117,"lng":-1.26383,"vibe":"historic LGBTQ+ pub where community groups feel at home","q":"Pride and group nights fill the small rooms; earlier visits are easier for conversation.","best":"Choose a community night or settle in before moving to Plush.","crowd":"LGBTQ+ locals and students across ages, trans groups, leather communities, gaymers and allies.","dress":"Pub casual; group events may invite theme wear.","staff":"Oxford Pride identifies it as one of the city's most cherished year-round LGBTQ+ spaces.","sources":["https://oxfordpride.uk/wp-content/uploads/2026/06/Oxford-Pride-Digital-Guide-2026.pdf","https://www.jollyfarmers.co.uk/"]},
 {"name":"Plush Oxford","city":"oxford","type":"club","description":"Oxford's dedicated LGBTQ+ late club drops beneath Frewin Court into a compact, high-energy dance floor of pop, drag, student nights and full-release Pride celebrations.","hours":"Late programmed nights; verify current doors, tickets and student promotions.","link":"https://www.plushoxford.com/","location":"Frewin Court, Oxford OX1 3HZ, United Kingdom","lat":51.75343,"lng":-1.26009,"vibe":"underground queer dance floor at the centre of Oxford nightlife","q":"Weekend and Pride editions queue late; advance tickets may apply.","best":"Arrive before the post-pub rush and check the night's audience and music.","crowd":"LGBTQ+ students, locals, drag audiences, gay men, queer women and allies.","dress":"Expressive clubwear to student-night casual.","staff":"Oxford Pride recognises Plush as a long-running affirming LGBTQ+ nightlife mainstay.","sources":["https://oxfordpride.uk/wp-content/uploads/2026/06/Oxford-Pride-Digital-Guide-2026.pdf","https://www.plushoxford.com/"]},
 {"name":"Common Ground Workspace","city":"oxford","type":"cafe","description":"A social-enterprise café and arts room in Jericho where queer talks, workshops and community events trade nightclub volume for coffee, ideas and genuine daytime connection.","hours":"Daytime café and event calendar vary; verify before travel.","link":"https://www.commongroundoxford.com/","location":"37-38 Little Clarendon Street, Oxford OX1 2HF, United Kingdom","lat":51.75770,"lng":-1.26323,"vibe":"progressive community café with thoughtful queer programming","q":"Small workshops can require booking; ordinary café hours are mixed.","best":"Attend an explicitly LGBTQ+ listing or use daytime for low-pressure conversation.","crowd":"Queer students, activists, artists, remote workers and mixed community groups.","dress":"Relaxed academic-creative casual.","staff":"Hosts documented Pride and queer community programming; permanent exclusivity is not claimed.","sources":["https://oxfordpride.uk/","https://www.commongroundoxford.com/"]},
 {"name":"The Nest Oxford","city":"oxford","type":"gallery","description":"An independent east-Oxford arts venue that can become a three-day queer-femme punk laboratory of live bands, zines, badges, open mics, DJs and art markets.","hours":"Event-led; queer identity applies only to named productions.","link":"https://www.instagram.com/thenestoxford/","location":"Oxford, United Kingdom","lat":51.74686,"lng":-1.23183,"vibe":"DIY arts space with a sharp queer-femme punk edge","q":"Small capacity and multi-day programmes may use separate tickets.","best":"Follow the organiser and attend an explicitly queer production.","crowd":"Queer femmes, punk audiences, zine makers, artists, students and allies.","dress":"DIY expressive and gig-ready.","staff":"Current 2026 queer-femme programming is documented; the venue is not labelled LGBTQ+ every night.","sources":["https://www.reddit.com/r/oxford/comments/1ots55x/does_oxford_have_any_kind_of_queercore_scene_or/","https://www.instagram.com/thenestoxford/"]},

 {"name":"Fincken","city":"bergen","type":"bar","description":"Bergen's first, longest-running and only full-time queer bar moves from Saturday coffee and pastries into a two-level pub-and-dance-floor night where every identity is invited to take up space.","hours":"Wednesday-Thursday 19:00-01:30, Friday 20:00-03:00, Saturday 12:00-03:00.","link":"https://www.fincken.no/","location":"Nygårdsgaten 2A, 5015 Bergen, Norway","lat":60.39020,"lng":5.32659,"vibe":"Bergen's essential queer clubhouse from café daylight to late dancing","q":"Saturday and Pride nights fill both levels; café hours are gentler.","best":"Start during Saturday Kafé Fincken, return later for the dance floor.","crowd":"All-gender LGBTQ+ locals, students, visitors, drag audiences and allies sharing progressive values.","dress":"Anything from rainwear to full dance-floor expression.","staff":"First-party operator explicitly identifies Fincken as Bergen's only official full-time queer hangout.","sources":["https://www.fincken.no/","https://en.visitbergen.com/visitor-information/lgbtiq-travel-in-bergen-gay-bars-and-inclusive-experiences"]},
 {"name":"Det Akademiske Kvarter on queer nights","city":"bergen","type":"club","description":"Bergen's student cultural house becomes a multi-room queer playground when Pride or student organisers take over, scaling the city's scene into cabaret, speed dating, kink, bears and open dance floors.","hours":"Event-led; ordinary operation is a mixed student venue.","link":"https://kvarteret.no/","location":"Olav Kyrres gate 49, 5015 Bergen, Norway","lat":60.38783,"lng":5.32270,"vibe":"student culture labyrinth transformed by ambitious queer takeovers","q":"Headline Pride events can sell out while later house-party portions may differ.","best":"Use the Bergen Pride or Kvarteret listing for exact room and ticket.","crowd":"Queer students, performers, bears, kink communities, women, migrants and allies on hosted nights.","dress":"Event-specific, with rain layers for arrival.","staff":"Queerness is attributed to named organisers and programmes, not the venue's ordinary mixed identity.","sources":["https://www.bergenpride.no/program-en/","https://kvarteret.no/"]},
 {"name":"USF Verftet on Bergen Pride nights","city":"bergen","type":"gallery","description":"A former sardine factory on the Nordnes waterfront gives Bergen Pride industrial-scale rooms for concerts, performance and community culture against the harbour's wet blue light.","hours":"Cultural programme varies; queer listing applies only to named events.","link":"https://usf.no/","location":"Georgernes Verft 12, 5011 Bergen, Norway","lat":60.39728,"lng":5.30858,"vibe":"waterfront arts factory amplified by queer festival production","q":"Large events use tickets and multiple rooms; the walk from town is exposed to rain.","best":"Attend a Bergen Pride or explicitly queer cultural listing and arrive early for waterfront orientation.","crowd":"Queer arts audiences, musicians, families, festival visitors and mixed culture crowds.","dress":"Creative layers and waterproof outerwear.","staff":"Documented festival host; no permanent LGBTQ+ exclusivity is claimed.","sources":["https://www.bergenpride.no/","https://usf.no/"]},

 {"name":"Bloom Santiago","city":"santiago_de_compostela","type":"club","description":"Two floors of drag, pop and late dancing make Bloom Compostela's clearest dedicated LGBT club, tucked into the stone maze of the old town.","hours":"Late nights from around 23:30; verify current social schedule.","link":"https://www.instagram.com/bloomsdc/","location":"Rúa da Algalia de Abaixo 22, 15704 Santiago de Compostela, Spain","lat":42.88231,"lng":-8.54216,"vibe":"compact old-town LGBT club with drag-led exuberance","q":"Weekend shows and Pride dates fill the two floors quickly.","best":"Arrive for the first drag set rather than the latest post-bar rush.","crowd":"LGBTQ+ students, gay men, queer women, drag audiences, pilgrims and allies.","dress":"Expressive clubwear that handles old-town cobbles.","staff":"Current 2026 nightlife sources identify Bloom as an active LGBT club and drag venue.","sources":["https://qlist.app/cities/Spain/Santiago-de-Compostela/278/es","https://www.instagram.com/bloomsdc/"]},
 {"name":"A Medusa Pub","city":"santiago_de_compostela","type":"bar","description":"A tiny cocktail and live-music pub near the market with deep feminist movement ties and lesbian-community history, offering a softer old-town counterpoint to Bloom's dance floor.","hours":"Evenings from around 19:00; verify current operator schedule.","link":"https://www.facebook.com/amedusapub/","location":"Praza de Salvador Parga 1, 15704 Santiago de Compostela, Spain","lat":42.88159,"lng":-8.54212,"vibe":"feminist cocktail nook with acoustic music and queer memory","q":"Terrace and live sets fill the compact room; cash/payment details should be checked.","best":"Early evening for cocktails or a currently listed feminist/queer event.","crowd":"Queer women, feminists, artists, students, locals and mixed friends.","dress":"Relaxed old-town creative casual.","staff":"Municipal women's map recognises A Medusa as a feminist reference and lesbian-event host.","sources":["https://tm.santiagodecompostela.gal/es/mapa/a-medusa","https://qlist.app/cities/Spain/Santiago-de-Compostela/278/es"]},
 {"name":"Tarasca","city":"santiago_de_compostela","type":"bar","description":"A cash-friendly late bar on Entremuros where indie spirit, low prices and an open-minded student crowd make it a dependable queer-friendly final stop without a rainbow-brand performance.","hours":"Wednesday-Thursday 23:30-04:00, Friday-Saturday 23:30-04:30; verify current listing.","link":"https://www.facebook.com/pages/Tarasca/112946682109763","location":"Rúa de Entremuros 13, 15704 Santiago de Compostela, Spain","lat":42.88118,"lng":-8.54114,"vibe":"cheap, late and alternative old-town bar with queer goodwill","q":"The room is busiest after 01:00 and may be cash-only.","best":"Late after A Medusa or Bloom when a mixed alternative crowd suits.","crowd":"Queer students, Galician music crowds, locals and international visitors.","dress":"Unpolished late-night casual and cobble-safe shoes.","staff":"Current local community identifies Tarasca as welcoming; it is not misrepresented as dedicated LGBT.","sources":["https://es.restaurantguru.com/Tarasca-Santiago-de-Compostela","https://www.reddit.com/r/SantiagodeCompostela/comments/18ajdhx/lgbt_question/"]},

 {"name":"HOSI Bar Salzburg","city":"salzburg","type":"bar","description":"The public bar inside HOSI Salzburg's bright street-level centre is the city's queer living room, moving between Ladies Night, drag bingo, quizzes, tours, advice and ordinary conversation.","hours":"Open to all Wednesday from 19:00 and Saturday from 20:00; additional events vary.","link":"https://hosi.or.at/","location":"Franz-Josef-Straße 22, 5020 Salzburg, Austria","lat":47.80793,"lng":13.04639,"vibe":"visible community bar where organising and nightlife share a counter","q":"Pride bingo and Ladies Night fill early; ordinary association evenings are calmer.","best":"Choose the identity or programme night that fits, or visit Wednesday to connect.","crowd":"LGBTQ+ Salzburg residents across ages, women, activists, drag fans, visitors and allies.","dress":"Come-as-you-are; event themes may invite sparkle.","staff":"Operated by Salzburg's dedicated LGBTIQ+ advocacy organisation in its public community centre.","sources":["https://hosi.or.at/kontakt/","https://www.queersalzburg.at/locations/hosi-bar/"]},
 {"name":"Dark Eagle","city":"salzburg","type":"cruise_club","description":"Salzburg's only bar with a basement cruising area and playrooms serves a men-only audience through fetish nights, puppy meet-ups, underwear afternoons and direct adult house rules.","hours":"Wednesday-Thursday 20:00-00:00, Friday-Saturday 20:00-02:00; special Sunday events. Verify current site.","link":"https://www.dark-eagle.at/","location":"Paracelsusstraße 11, 5020 Salzburg, Austria","lat":47.80947,"lng":13.04799,"vibe":"men-only fetish and cruising bar with a programmed basement","q":"Fetish and underwear themes change admission and crowd; identification may be required.","best":"Read the full theme and house rules before choosing a night.","crowd":"Adult gay and bisexual men, fetish communities, pups, locals and visitors.","dress":"Streetwear, underwear or fetish according to the specific programme.","staff":"First-party operator states men-only scope; Queer Salzburg confirms the city's only cruising-area bar.","sources":["https://www.dark-eagle.at/dark-eagle/die-bar/","https://www.queersalzburg.at/salzburg-guide/bars-restaurants/"]},
 {"name":"NarrenCastl","city":"salzburg","type":"bar","description":"A colourful Lehen neighbourhood pub with a small cabaret stage where Magic Garage travesty and recurring queer karaoke bring camp performance into a genuinely local room.","hours":"Monday, Tuesday and Thursday 18:00-22:00; Wednesday, Friday and Saturday 18:00-23:00.","link":"https://www.narrencastl.at/","location":"Rudolf-Biebl-Straße 22, 5020 Salzburg, Austria","lat":47.80861,"lng":13.02690,"vibe":"friendly neighbourhood pub with irregular bursts of queer cabaret","q":"Karaoke and travesty nights fill faster than ordinary pub evenings.","best":"Attend a listed queer karaoke, Stammtisch or Magic Garage date.","crowd":"Queer locals, karaoke singers, cabaret fans, neighbours and allies.","dress":"Relaxed pub style to playful performance-night looks.","staff":"Official queer city guide marks it gay-friendly and documents current queer programming.","sources":["https://www.queersalzburg.at/en/locations/narrencastl/","https://www.narrencastl.at/contact"]},
 {"name":"Furo Salzburg","city":"salzburg","type":"restaurant","description":"A vegetarian-vegan restaurant whose colourful plates and recurring Pride brunches create a bright daytime table for queer Salzburg before the evening programme begins.","hours":"Restaurant schedule varies; queer relevance is tied to announced Pride brunches.","link":"https://www.instagram.com/furo_salzburg/","location":"Salzburg, Austria","lat":47.80288,"lng":13.04325,"vibe":"plant-based daytime social with Pride-brunch sparkle","q":"Pride brunch tables need reservations; ordinary service is mixed.","best":"Reserve a named Pride brunch and confirm dietary/access needs.","crowd":"Queer friends, couples, vegans, brunch groups and allies.","dress":"Bright casual daytime style.","staff":"Official 2026 Pride calendar documents repeated queer brunch partnership; permanent exclusivity is not claimed.","sources":["https://www.queersalzburg.at/","https://www.instagram.com/furo_salzburg/"]},
 {"name":"ARGEkultur on HOSI Fest nights","city":"salzburg","type":"club","description":"Nonntal's major independent culture house expands Salzburg's queer scene across two floors for HOSI Fest, pairing mainstream house, techno and neon performance at western Austria's largest queer club night.","hours":"Event-led; ordinary ARGEkultur programming is mixed.","link":"https://www.argekultur.at/","location":"Ulrike-Gschwandtner-Straße 5, 5020 Salzburg, Austria","lat":47.79363,"lng":13.05079,"vibe":"large cultural complex electrified by two-floor queer production","q":"HOSI Fest uses presale tickets and can reach capacity.","best":"Arrive through Pride Park, then enter before the headline set.","crowd":"LGBTIQA+ dancers across western Austria, students, performers and allies.","dress":"Neon-friendly clubwear with late-night weather layers.","staff":"Queer identity is attributed to HOSI Fest, officially described as western Austria's largest queer clubbing event.","sources":["https://www2.salzburg.info/en/events/events-calendar/hosi-fest-pride-festival-2026_event_41349897","https://www.argekultur.at/"]}
]
$qa_places$) p(name text,city text,type text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,q text,best text,crowd text,dress text,staff text,sources jsonb)
), places as (select p.*,jsonb_build_object('queue_wait',q,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',staff,'source_urls',sources,'research_status','current_operator_destination_and_community_sources','updated_at','2026-08-28T00:00:00Z') intel from raw_places p), upd as (update public.places t set type=p.type,description=p.description,hours=p.hours,link=p.link,location=p.location,lat=p.lat,lng=p.lng,vibe=p.vibe,vibe_tags=array[]::text[],venue_intel=p.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from places p where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)) returning t.id)
insert into public.places(name,city,type,description,hours,link,location,lat,lng,vibe,vibe_tags,venue_intel,seo_indexable,seo_quality_status,updated_at) select name,city,type,description,hours,link,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from places p where not exists(select 1 from public.places t where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)));

with raw_events as (
 select * from jsonb_to_recordset($qa_events$
[
 {"name":"Iruña Harro 2026","city":"pamplona","description":"Pamplona's June Pride programme linked workshops, culture, sport and community action before a final weekend of public gathering, drag and a rights-focused march.","link":"https://www.pamplona.es/actualidad/noticias/el-ayuntamiento-de-pamplona-colabora-con-colectivos-y-asociaciones-lgtbi-en-el","date":"2026-06-01","start_date":"2026-06-01T10:00:00+02:00","end_date":"2026-06-28T18:00:00+02:00","location":"Multiple venues and central Pamplona, Spain","lat":42.81250,"lng":-1.64580,"vibe":"bilingual civic Pride grounded in rights and community participation","q":"Individual workshops, pre-Pride and march events use separate registration and timings.","best":"Use the municipal programme and arrive early for Recoletas and the march assembly.","crowd":"LGBTQI+ Navarrese people, families, activists, performers and allies.","dress":"Pride expression with sun protection and walking shoes.","host":"Pamplona City Council with Harrotu, Kattalingorri, Dekumas and local collectives.","sources":["https://www.pamplona.es/actualidad/noticias/el-ayuntamiento-de-pamplona-colabora-con-colectivos-y-asociaciones-lgtbi-en-el","https://www.redpobreza.org/agenda/tarde-pre-pride-2026/"]},
 {"name":"Oxford Pride 2026","city":"oxford","description":"Oxford Pride returned on 6 June with a city procession and venue-led programme that kept celebration rooted in local LGBTQ+ pubs, clubs and community spaces.","link":"https://oxfordpride.uk/oxford-pride-2026/","date":"2026-06-06","start_date":"2026-06-06T10:00:00+01:00","end_date":"2026-06-07T03:00:00+01:00","location":"Central Oxford and partner venues, United Kingdom","lat":51.75200,"lng":-1.25770,"vibe":"town-and-gown Pride flowing through Oxford's own queer rooms","q":"Procession, daytime community events and club afterparties have separate capacity.","best":"Read the digital guide, join the procession early and reserve late events.","crowd":"LGBTQIA+ residents, students, families, academics, performers and allies.","dress":"Pride expression with rain layer and walking shoes.","host":"Oxford Pride is the city's established LGBTQIA+ volunteer-led festival organisation.","sources":["https://oxfordpride.uk/preparing-for-oxford-pride-2026/","https://oxfordpride.uk/wp-content/uploads/2026/06/Oxford-Pride-Digital-Guide-2026.pdf"]},
 {"name":"Bergen Pride 2026","city":"bergen","description":"Norway's second-largest Pride filled central Bergen with queer culture, Pride Park and a rain-or-shine parade culminating on 6 June 2026.","link":"https://www.bergenpride.no/","date":"2026-05-29","start_date":"2026-05-29T18:00:00+02:00","end_date":"2026-06-06T23:00:00+02:00","location":"Central Bergen and multiple cultural venues, Norway","lat":60.39130,"lng":5.32210,"vibe":"west-coast Pride joining public visibility and serious queer culture","q":"Shows, Pride Park and parade use separate access and weather plans.","best":"Build a programme from the official schedule and waterproof everything.","crowd":"Queer people across western Norway, families, artists, migrants, visitors and allies.","dress":"Pride colour beneath genuinely waterproof layers.","host":"Bergen Pride/Regnbuedagene is the city's established queer festival organisation.","sources":["https://www.bergenpride.no/","https://www.bergenpride.no/program-en/"]},
 {"name":"Compostela Pride Gala 2026","city":"santiago_de_compostela","description":"The municipal campaign Against Hate: Network, Culture and Pride culminated in a public gala at Praza de Mazarelos on 27 June, joining performance, poetry and activist visibility.","link":"https://cimcompostela.santiagodecompostela.gal/es/la-alcaldesa-de-santiago-presenta-la-campana-contra-el-odio-red-cultura-y-orgullo-para-avanzar-contra-la-lgtbifobia/","date":"2026-06-27","start_date":"2026-06-27T18:00:00+02:00","end_date":"2026-06-27T23:30:00+02:00","location":"Praza de Mazarelos, Santiago de Compostela, Spain","lat":42.87889,"lng":-8.54162,"vibe":"Galician civic Pride mixing art, memory and resistance to hate","q":"Public-square capacity and weather affect viewing; linked activities run throughout June.","best":"Arrive early for the square and follow municipal access information.","crowd":"LGBTQ+ Galicians, students, artists, families, activists and allies.","dress":"Pride expression with rain layer and cobble-safe shoes.","host":"Santiago City Council with Avante LGBT+ and cultural partners.","sources":["https://cimcompostela.santiagodecompostela.gal/es/la-alcaldesa-de-santiago-presenta-la-campana-contra-el-odio-red-cultura-y-orgullo-para-avanzar-contra-la-lgtbifobia/","https://www.planomato.com/es/santiago-de-compostela/p/gala-orgullo-santiago-2026"]},
 {"name":"Pride Festival Salzburg 2026","city":"salzburg","description":"Ten days from 28 August to 6 September turn Mozart's city into a queer stage of bingo, karaoke, food, museums, workshops, parade and the two-floor HOSI Fest.","link":"https://pridefestival.at/","date":"2026-08-28","start_date":"2026-08-28T18:00:00+02:00","end_date":"2026-09-06T18:00:00+02:00","location":"Multiple venues across Salzburg, Austria","lat":47.80950,"lng":13.05500,"vibe":"baroque citywide Pride with an unusually theatrical programme","q":"Around thirty events use distinct reservations, tickets and audience rules.","best":"Build the ten-day calendar early and reserve HOSI Fest, drag and brunch formats.","crowd":"LGBTIQA+ Salzburg residents, western Austrian visitors, artists, families and allies.","dress":"Event-specific Pride expression with late-summer layers.","host":"HOSI Salzburg and the Pride team organise the official citywide festival.","sources":["https://www.salzburg.info/en/events/events-calendar/pride-week-salzburg_event_40064483","https://www.queersalzburg.at/"]}
]
$qa_events$) e(name text,city text,description text,link text,date text,start_date timestamptz,end_date timestamptz,location text,lat double precision,lng double precision,vibe text,q text,best text,crowd text,dress text,host text,sources jsonb)
), events as (select e.*,jsonb_build_object('entry_wait',q,'best_arrival',best,'crowd_mix',crowd,'dress_code',dress,'host_inclusivity',host,'source_urls',sources,'research_status','latest_official_or_organiser_schedule','updated_at','2026-08-28T00:00:00Z') intel from raw_events e), upd as (update public.events t set description=e.description,link=e.link,date=e.date,start_date=e.start_date,end_date=e.end_date,location=e.location,lat=e.lat,lng=e.lng,vibe=e.vibe,vibe_tags=array[]::text[],event_intel=e.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from events e where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)) returning t.id)
insert into public.events(name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at) select name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from events e where not exists(select 1 from public.events t where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)));

with raw_services as (
