[
 {"name":"Harrotu Information and Support","city":"pamplona","type":"other","provider":"Pamplona City Council / Harrotu","contact":"harrotu@pamplona.es | +34 948 226 326 | +34 699 384 965","booking":"https://www.pamplona.es/temas/igualdad-y-lgtbi/harrotu","description":"Confidential municipal LGTBI service providing information, psychosocial support, rights promotion, participation, referrals and anonymous incident recording.","hours":"Staffed winter and summer schedules differ; contact before a support visit.","link":"https://www.pamplona.es/temas/igualdad-y-lgtbi/harrotu","location":"Calle San Gregorio 28, 31001 Pamplona, Spain","lat":42.81711,"lng":-1.64689,"vibe":"professional public support with community-centre warmth","lead":"Contact ahead for counselling or protected appointments; library visits can use staffed hours.","best":"Private weekday contact with language and access needs stated.","crowd":"LGBTQI+ residents, witnesses of hate, families, migrants and community groups.","prep":"Clarify support, participation, library or incident-reporting need.","incl":"Dedicated municipal LGTBI service with confidential professional care.","sources":["https://www.pamplona.es/temas/igualdad-y-lgtbi/harrotu"]},
 {"name":"Kattalingune Navarra","city":"pamplona","type":"other","provider":"Kattalingorri / Government of Navarra","contact":"Use current Kattalingune contact route","booking":"https://www.igualdadnavarra.es/es/kattalingune","description":"Navarra-wide LGTBI+ information and support connects Pamplona users with rights guidance, sexological and legal orientation, community resources and regional referrals.","hours":"Appointment and published office schedule; verify before attending.","link":"https://www.igualdadnavarra.es/es/kattalingune","location":"Pamplona, Navarra, Spain","lat":42.81250,"lng":-1.64580,"vibe":"regional queer support linking city and rural Navarra","lead":"Contact before travel and state municipality, language and service need.","best":"Weekday private enquiry for the correct professional or local route.","crowd":"LGTBI+ people across Navarra, families, professionals and community organisations.","prep":"Ask about confidentiality, language, office location and appointment format.","incl":"Dedicated public LGTBI+ service managed by specialist collective Kattalingorri.","sources":["https://www.pamplona.es/entidades/colectivo-kattalingorri","https://www.igualdadnavarra.es/es/kattalingune"]},
 {"name":"Oxford Pride Community Network","city":"oxford","type":"other","provider":"Oxford Pride","contact":"Use official contact and volunteer channels","booking":"https://oxfordpride.uk/","description":"Year-round Pride organisation connecting Oxford's LGBTQIA+ residents with community events, inclusive swimming, volunteering, venue partners and the annual festival.","hours":"Online year-round; events by published schedule.","link":"https://oxfordpride.uk/","location":"Oxford, United Kingdom","lat":51.75200,"lng":-1.25770,"vibe":"citywide queer network bridging community and celebration","lead":"Use the current calendar and contact ahead for access, volunteering or partnership needs.","best":"Check several weeks ahead for limited free formats such as the Big Swim.","crowd":"LGBTQIA+ residents, families, volunteers, performers, students and allies.","prep":"Confirm booking, age, accessibility and safeguarding for each activity.","incl":"Dedicated Oxford LGBTQIA+ Pride and community organisation.","sources":["https://oxfordpride.uk/","https://oxfordpride.uk/wp-content/uploads/2026/06/Oxford-Pride-Digital-Guide-2026.pdf"]},
 {"name":"Oxford Friend","city":"oxford","type":"wellness","provider":"Oxford Friend / Oxfordshire Mind","contact":"Use the current Oxfordshire Mind LGBTQIA+ contact route","booking":"https://www.oxfordshiremind.org.uk/support-for-you/lgbtqia/","description":"Confidential LGBTQIA+ listening and wellbeing support offers a route beyond university services for people across Oxfordshire.","hours":"Helpline and group schedules vary; verify the current provider page.","link":"https://www.oxfordshiremind.org.uk/support-for-you/lgbtqia/","location":"Oxford and Oxfordshire, United Kingdom","lat":51.75200,"lng":-1.25770,"vibe":"confidential local listening with mental-health referral depth","lead":"Check service hours and contact privately before expecting in-person support.","best":"Use a quiet setting and describe urgency, age and preferred contact method.","crowd":"LGBTQIA+ people across Oxfordshire, including students and non-students.","prep":"Ask about confidentiality, waiting time, crisis limits and group eligibility.","incl":"Dedicated LGBTQIA+ support within a specialist local mental-health charity.","sources":["https://www.oxfordshiremind.org.uk/support-for-you/lgbtqia/"]},
 {"name":"FRI Vestland","city":"bergen","type":"other","provider":"FRI - Foreningen for kjønns- og seksualitetsmangfold Vestland","contact":"Use official regional contact","booking":"https://www.foreningenfri.no/fylkeslag/fri-vestland/","description":"Regional queer rights organisation coordinates groups, advocacy, Pride collaboration and community connection across Bergen and western Norway.","hours":"Volunteer and programme-led; contact before any office visit.","link":"https://www.foreningenfri.no/fylkeslag/fri-vestland/","location":"Bergen, Norway","lat":60.39130,"lng":5.32210,"vibe":"west-coast queer organising with deep Pride infrastructure","lead":"Contact ahead for the correct group, referral or volunteer route.","best":"Use the current calendar rather than relying on a fixed drop-in assumption.","crowd":"LGBTQ+ people across Vestland, activists, families, youth and volunteers.","prep":"State municipality, language, privacy and access needs.","incl":"Dedicated regional branch of Norway's national gender and sexuality diversity organisation.","sources":["https://www.foreningenfri.no/fylkeslag/fri-vestland/","https://www.bergenpride.no/"]},
 {"name":"Skeiv Verden Vest","city":"bergen","type":"other","provider":"Skeiv Verden Vest","contact":"Use official regional contact","booking":"https://www.skeivverden.no/vest","description":"Peer-led support and social community for LGBTQ+ people with minority and migration backgrounds, offering a culturally specific route often missing from mainstream nightlife.","hours":"Programme and appointment-led.","link":"https://www.skeivverden.no/vest","location":"Bergen, Norway","lat":60.39130,"lng":5.32210,"vibe":"intersectional queer migrant community built around belonging","lead":"Contact ahead and ask about language, group eligibility and privacy.","best":"Join a named group or event after direct confirmation.","crowd":"LGBTQ+ migrants, refugees, racialised Norwegians and invited allies.","prep":"Confirm confidentiality, interpretation, location and registration.","incl":"Dedicated queer minority organisation with an active western Norway branch.","sources":["https://www.skeivverden.no/vest","https://www.skeivverden.no/wp-content/uploads/2025/05/Arsrapport.2024.godkjent.Skeiv-Verden-Vest.pdf"]},
 {"name":"Avante LGBT+ Compostela","city":"santiago_de_compostela","type":"other","provider":"Avante LGBT+","contact":"Use official contact and assembly channels","booking":"https://avantelgbt.com/","description":"Santiago-founded activist association organises assemblies, Pride, education, cultural work and anti-hate response across Galicia.","hours":"Volunteer and programme-led; no daily walk-in assumption.","link":"https://avantelgbt.com/","location":"Santiago de Compostela, Spain","lat":42.87820,"lng":-8.54480,"vibe":"Galician queer organising rooted in public visibility and mutual support","lead":"Contact ahead for assemblies, support, volunteering or incident response.","best":"Use the current local assembly calendar and official private channels.","crowd":"LGBTQ+ Galicians, activists, students, families and cultural workers.","prep":"Clarify city, privacy, language and whether the need is support or organising.","incl":"Dedicated LGBTQ+ association founded in Santiago in 2017.","sources":["https://avantelgbt.com/index.php/quen-somos/","https://cimcompostela.santiagodecompostela.gal/es/la-alcaldesa-de-santiago-presenta-la-campana-contra-el-odio-red-cultura-y-orgullo-para-avanzar-contra-la-lgtbifobia/"]},
 {"name":"Troula Segura Nightlife Support","city":"santiago_de_compostela","type":"other","provider":"Santiago de Compostela City Council / CIM","contact":"Use municipal equality and emergency channels","booking":"https://cimcompostela.santiagodecompostela.gal/es/troula-segura-es/","description":"Municipal nightlife protocol trains participating venues to prevent, detect and respond to sexual violence and LGTBIfobia.","hours":"Active through participating venues during their opening hours; municipal information online.","link":"https://cimcompostela.santiagodecompostela.gal/es/troula-segura-es/","location":"Participating nightlife venues across Santiago de Compostela, Spain","lat":42.87820,"lng":-8.54480,"vibe":"citywide safer-nightlife network with trained intervention routes","lead":"Identify participating venues before going out and ask staff immediately when help is needed.","best":"Save the protocol and emergency contacts before a late night.","crowd":"All nightlife users, with explicit protection against sexual violence and LGTBIfobia.","prep":"Know the venue name, location and whether immediate danger requires emergency services.","incl":"Explicit municipal anti-LGTBIfobia prevention and response protocol.","sources":["https://cimcompostela.santiagodecompostela.gal/es/troula-segura-es/"]},
 {"name":"HOSI Salzburg Counselling","city":"salzburg","type":"other","provider":"HOSI Salzburg","contact":"office@hosi.or.at | +43 662 435927","booking":"https://hosi.or.at/beratungsanfrage","description":"Salzburg's LGBTIQ+ advocacy centre provides counselling, information, community groups, education, legal-social orientation and direct connection to the city's queer programme.","hours":"Office Monday-Thursday 09:00-15:00, Friday 09:00-12:00; arrange a reliable appointment.","link":"https://hosi.or.at/","location":"Franz-Josef-Straße 22, 5020 Salzburg, Austria","lat":47.80793,"lng":13.04639,"vibe":"experienced queer advocacy under the same roof as community life","lead":"Submit a counselling request before visiting.","best":"Private weekday appointment with urgency and access needs clear.","crowd":"LGBTIQ+ people, families, youth, older adults, volunteers and allies.","prep":"State preferred contact method, confidentiality and language requirements.","incl":"Dedicated Salzburg LGBTIQ+ advocacy organisation founded in 1980.","sources":["https://hosi.or.at/kontakt/","https://hosi.or.at/"]},
 {"name":"Aidshilfe Salzburg","city":"salzburg","type":"wellness","provider":"Aidshilfe Salzburg","contact":"Use official testing and counselling contact","booking":"https://www.aidshilfe-salzburg.at/","description":"Confidential HIV and STI counselling, testing, prevention and psychosocial support with established competence for gay, bi and wider queer communities.","hours":"Testing and counselling by published schedule or appointment.","link":"https://www.aidshilfe-salzburg.at/","location":"Salzburg, Austria","lat":47.80950,"lng":13.05500,"vibe":"low-threshold sexual health with specialist queer knowledge","lead":"Check test windows and book where required.","best":"Attend early in the testing period with window-time questions prepared.","crowd":"LGBTQ+ people, people living with HIV and anyone seeking confidential sexual-health advice.","prep":"Confirm cost, anonymity, test window periods and result timing.","incl":"Established HIV/STI provider working directly with Salzburg's queer community network.","sources":["https://www.aidshilfe-salzburg.at/","https://www.queersalzburg.at/"]}
]
$qa_services$) s(name text,city text,type text,provider text,contact text,booking text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,lead text,best text,crowd text,prep text,incl text,sources jsonb)
), services as (select s.*,jsonb_build_object('booking_lead_time',lead,'best_time',best,'client_mix',crowd,'preparation',prep,'provider_inclusivity',incl,'source_urls',sources,'research_status','current_first_party_service_source','updated_at','2026-08-28T00:00:00Z') intel from raw_services s), upd as (update public.services t set type=s.type,provider_name=s.provider,contact=s.contact,booking_link=s.booking,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],source='Official/provider sources; checked 2026-08-28',"lastChecked"=date '2026-08-28',verified=true,service_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from services s where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)) returning t.id)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,vibe_tags,source,"lastChecked",verified,service_intel,seo_indexable,seo_quality_status,updated_at) select name,city,type,provider,contact,booking,description,hours,link,location,lat,lng,vibe,array[]::text[],'Official/provider sources; checked 2026-08-28',date '2026-08-28',true,intel,true,'approved',timezone('utc',now()) from services s where not exists(select 1 from public.services t where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)));

select public.qa_refresh_city_seo_status(slug) from (values('pamplona'),('oxford'),('bergen'),('santiago_de_compostela'),('salzburg')) v(slug) where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select c.slug,c.name,c.verified_place_count,c.seo_indexable,c.seo_requirements from public.qa_cities c where c.slug in('pamplona','oxford','bergen','santiago_de_compostela','salzburg') order by c.slug;
